from collections import deque

def topological_ordering(nodes):
    ordered_nodes = deque()

    # Initialize with nodes without incoming edges
    for node in nodes:
        if not node.incoming_edges:
            ordered_nodes.append(node)

    while ordered_nodes:
        current_node = ordered_nodes.popleft()

        # Add outgoing edges to the queue
        for next_node in current_node.outgoing_edges:
            if next_node not in ordered_nodes:
                ordered_nodes.append(next_node)

    return list(ordered_nodes)
