from collections import deque
from typing import List, Set

class Node:
    def __init__(self, value):
        self.value = value
        self.outgoing_edges = []
        self.incoming_edges = []

    def add_edge(self, other_node):
        self.outgoing_edges.append(other_node)
        other_node.incoming_edges.append(self)

    def __str__(self):
        return f"Node({self.value})"

def topological_sort(nodes: List[Node]) -> List[Node]:
    # Create adjacency lists
    adjacency_list = {node: set() for node in nodes}

    # Populate adjacency lists
    for node in nodes:
        for outgoing_edge in node.outgoing_edges:
            adjacency_list[node].add(outgoing_edge)

    # Initialize queue with nodes with no incoming edges
    queue = deque(node for node in nodes if not node.incoming_edges)

    # Perform topological sort
    sorted_nodes = []
    while queue:
        current_node = queue.popleft()
        sorted_nodes.append(current_node)
        for adjacent_node in adjacency_list[current_node]:
            adjacent_node.incoming_edges.remove(current_node)
            if not adjacent_node.incoming_edges:
                queue.append(adjacent_node)

    # Check if the graph is acyclic
    if len(sorted_nodes) != len(nodes):
        raise ValueError("Graph contains cycles")

    return sorted_nodes

# Example usage
nodes = [
    Node('A'),
    Node('B'),
    Node('C'),
    Node('D')
]

edges = [
    ('A', 'B'),
    ('B', 'C'),
    ('C', 'D'),
    ('D', 'A')  # This creates a cycle
]

for edge in edges:
    nodes[edge[0]].add_edge(nodes[edge[1]])

try:
    print(topological_sort(nodes))
except ValueError as e:
    print(e)
